static unsigned char g_font_atlas_alpha[SQW_FONT_ATLAS_W * SQW_FONT_ATLAS_H];

static int sqw_hex_nibble(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    return c - 'A' + 10;
}

static void sqw_font_atlas_decode(void) {
    int out = 0;
    int ci = 0;
    while (g_font_atlas_hex_chunks[ci] != 0) {
        const char *s = g_font_atlas_hex_chunks[ci];
        int i = 0;
        while (s[i] != 0 && s[i+1] != 0) {
            int hi = sqw_hex_nibble(s[i]);
            int lo = sqw_hex_nibble(s[i+1]);
            g_font_atlas_alpha[out] = (unsigned char)((hi << 4) | lo);
            out = out + 1;
            i = i + 2;
        }
        ci = ci + 1;
    }
    sqw_font_metrics_init();
}

